def get_winner(n):
    memo = {}

    def solve(chosen, alice_set, bob_set, turn):
        state = (frozenset(chosen), frozenset(alice_set), frozenset(bob_set), turn)
        if state in memo:
            return memo[state]

        if len(chosen) == n:
            return 0  # DRAW

        # current_player is 'A' or 'B'
        current_set = alice_set if turn == 'A' else bob_set

        valid_moves = []
        for i in range(1, n + 1):
            if i not in chosen:
                # Rule (ii): cannot choose a number consecutive to any already chosen by this player
                is_consecutive = False
                for val in current_set:
                    if abs(i - val) == 1:
                        is_consecutive = True
                        break
                if not is_consecutive:
                    valid_moves.append(i)

        if not valid_moves:
            # Current player loses. 
            # If turn was 'A', Alice loses (-1). If turn was 'B', Alice wins (1).
            res = -1 if turn == 'A' else 1
            memo[state] = res
            return res

        results = []
        for move in valid_moves:
            new_chosen = chosen | {move}
            new_alice = alice_set | {move} if turn == 'A' else alice_set
            new_bob = bob_set | {move} if turn == 'B' else bob_set
            new_turn = 'B' if turn == 'A' else 'A'
            results.append(solve(new_chosen, new_alice, new_bob, new_turn))

        if turn == 'A':
            # Alice wants to maximize the result (1 > 0 > -1)
            res = max(results)
        else:
            # Bob wants to minimize the result (-1 < 0 < 1)
            res = min(results)

        memo[state] = res
        return res

    return solve(set(), set(), set(), 'A')

